LINE_RE = re.compile(r"^(?P<speaker>[^:]+):\s*(?P<text>.+?)\s*->\s*(?P<target>[A-Za-z0-9_]+)\s*$")


def parse_script(text: str):
    lines = text.splitlines()
    sections: list[tuple[str, list[str]]] = []
    current_id = None
    current_body: list[str] = []

    for raw_line in lines:
        line = raw_line.strip()
        if not line:
            continue

        section_match = SECTION_RE.match(line)
        if section_match:
            if current_id is not None:
                sections.append((current_id, current_body))
            current_id = section_match.group("id")
            current_body = []
            continue

        if current_id is None:
            raise ValueError(f"Content outside section: {line}")

        current_body.append(line)

    if current_id is not None:
        sections.append((current_id, current_body))

    nodes = []
    edges = []
    node_ids = []

    for section_id, body in sections:
        if not body:
            raise ValueError(f"Section '{section_id}' is empty")

        first = body[0]
        choice_match = CHOICE_RE.match(first)
        line_match = LINE_RE.match(first)

        if choice_match:
            node = {
                "id": section_id,
                "text": "",
                "speaker": "",
                "type": "choice",
            }

            for entry in body:
                match = CHOICE_RE.match(entry)
                if not match:
                    raise ValueError(f"Invalid choice line in '{section_id}': {entry}")
                edges.append(
                    {
                        "from": section_id,
                        "to": match.group("target"),
                        "text": match.group("text"),
                    }
                )
        elif line_match:
            node = {
                "id": section_id,
                "text": line_match.group("text"),
                "speaker": line_match.group("speaker"),
                "type": "line",
            }

            if len(body) != 1:
                raise ValueError(f"Line node '{section_id}' has unexpected extra content")

            edges.append(
                {
                    "from": section_id,
                    "to": line_match.group("target"),
                    "text": "",
                }
            )
        else:
            raise ValueError(f"Unknown section format in '{section_id}'")

        nodes.append(node)
        node_ids.append(section_id)

    node_set = set(node_ids)
    for edge in edges:
        if edge["to"] != "End" and edge["to"] not in node_set:
            raise ValueError(f"Missing target node: {edge['to']}")

    adjacency: dict[str, list[str]] = {}
    for edge in edges:
        adjacency.setdefault(edge["from"], []).append(edge["to"])

    reachable = set()
    start = node_ids[0]
    queue = deque([start])

    while queue:
        current = queue.popleft()
        if current in reachable:
            continue
        reachable.add(current)

        for target in adjacency.get(current, []):
            if target != "End" and target not in reachable:
                queue.append(target)

    unreachable = sorted(node_set - reachable)
    if unreachable:
        raise ValueError(f"Unreachable nodes detected: {', '.join(unreachable)}")

    return {"nodes": nodes, "edges": edges}


def graph_to_dot(graph: dict) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;"]

    for node in graph["nodes"]:
        shape = "diamond" if node["type"] == "choice" else "box"
        label_parts = [node["id"]]
        if node["speaker"]:
            label_parts.append(f"{node['speaker']}: {node['text']}")
        elif node["text"]:
            label_parts.append(node["text"])
        label = "\\n".join(part.replace('"', '\\"') for part in label_parts)
        lines.append(f'  "{node["id"]}" [shape={shape}, label="{label}"];')

    lines.append('  "End" [shape=doublecircle];')

    for edge in graph["edges"]:
        label = edge["text"].replace('"', '\\"')
        if label:
            lines.append(f'  "{edge["from"]}" -> "{edge["to"]}" [label="{label}"];')
        else:
            lines.append(f'  "{edge["from"]}" -> "{edge["to"]}";')

    lines.append("}")
    return "\n".join(lines)


if __name__ == "__main__":
    script_path = Path("/app/script.txt")
    graph = parse_script(script_path.read_text())

    Path("/app/dialogue.json").write_text(json.dumps(graph, indent=2))
    Path("/app/dialogue.dot").write_text(graph_to_dot(graph))
